-- Compiler objects of one deployment schema (docs/SPEC-compiler-dbt.md §3.4).
-- Generated by `uv run python -m bob_killer.hosts.snowflake.ddl`; do not edit.
-- Run as BOB_KILLER_OWNER in the deployment schema (APP or TEST_<uuid8>),
-- after 10_tables.sql.
-- DBT_SRC holds each run's files: @DBT_SRC/<run_id>/{workbook.db, ir.yaml, dbt/, docs/};
-- @DBT_SRC/_reviews/ holds the name review files (hosts/snowflake/reviews/).
CREATE STAGE IF NOT EXISTS DBT_SRC
  ENCRYPTION = (TYPE = 'SNOWFLAKE_SSE')
  DIRECTORY = (ENABLE = TRUE);

CREATE TABLE IF NOT EXISTS WB_INPUT_CELLS (
  run_id VARCHAR NOT NULL,
  sheet VARCHAR NOT NULL,
  cell_row NUMBER(38,0) NOT NULL,
  cell_col NUMBER(38,0) NOT NULL,
  node_id VARCHAR NOT NULL,
  value VARIANT NOT NULL,
  _seq NUMBER AUTOINCREMENT ORDER,
  _written_at TIMESTAMP_TZ DEFAULT CURRENT_TIMESTAMP(),
  PRIMARY KEY (run_id, sheet, cell_row, cell_col)
);
